const get=(store,id)=>{const d=(store.disciples||[]).find(x=>x.id===id&&x.status==='active');if(!d)throw Object.assign(new Error('Approved active Disciple not found.'),{statusCode:404});return d;};
export function buildLeaderBundleEmail({disciple}){return {subject:'Your complimentary Kingdom Leader Experience Bundle',text:`${disciple.name}, your Kingdom Leader Experience Bundle is complimentary. We will follow up with fulfillment details.`};}
export function buildMemberBundleInvitation({disciple,checkoutUrl}){return {subject:'Optional Kingdom Disciple Experience Bundle',text:`${disciple.name}, you may purchase the Kingdom Disciple Experience Bundle here: ${checkoutUrl}\n\nOptional purchase—no purchase is required to participate or earn commissions.`};}
export function awardLeaderBundle(store,input,deps={}){store.discipleBundleActions||=[];store.orders||=[];const disciple=get(store,input.discipleId);if(!disciple.isKingdomLeader)throw Object.assign(new Error('An active Kingdom Leader is required.'),{statusCode:400});const prior=store.discipleBundleActions.find(x=>x.discipleId===disciple.id&&x.campaignId===input.campaignId&&x.mode==='complimentary');if(prior)return prior;const now=(deps.now||(()=>new Date().toISOString()))(),id=deps.id;if(typeof id!=='function')throw new Error('id generator is required.');const order={id:id('ord'),orderType:'disciple_leader_bundle',discipleId:disciple.id,eventId:String(input.eventId||''),productIds:Array.isArray(input.productIds)?input.productIds:[],amountSubtotal:0,amountTotal:0,status:'fulfillment_pending',commissionEligible:false,createdAt:now};store.orders.push(order);const action={id:id('bundle'),discipleId:disciple.id,campaignId:String(input.campaignId),mode:'complimentary',orderId:order.id,status:'created',reason:String(input.reason||''),actorId:input.actorId,createdAt:now,email:buildLeaderBundleEmail({disciple})};store.discipleBundleActions.push(action);return action;}
export function inviteMemberBundle(store,input,deps={}){store.discipleBundleActions||=[];const disciple=get(store,input.discipleId);if(disciple.isKingdomLeader)throw Object.assign(new Error('Optional paid invitations are for approved non-Leader team members.'),{statusCode:400});if(!/^https:\/\//.test(String(input.checkoutUrl||'')))throw Object.assign(new Error('A secure checkout URL is required.'),{statusCode:400});const prior=store.discipleBundleActions.find(x=>x.discipleId===disciple.id&&x.campaignId===input.campaignId&&x.mode==='paid_optional');if(prior)return prior;const now=(deps.now||(()=>new Date().toISOString()))(),id=deps.id;const action={id:id('bundle'),discipleId:disciple.id,campaignId:String(input.campaignId),mode:'paid_optional',checkoutUrl:String(input.checkoutUrl),expiresAt:String(input.expiresAt||''),status:'invitation_pending',actorId:input.actorId,createdAt:now,email:buildMemberBundleInvitation({disciple,checkoutUrl:input.checkoutUrl})};store.discipleBundleActions.push(action);return action;}
